import express from "express";
import path from "path";
import { createServer as createViteServer } from "vite";
import Database from "better-sqlite3";

const db = new Database("app.db");

// Initialize table
db.exec(`
  CREATE TABLE IF NOT EXISTS store (
    key TEXT PRIMARY KEY,
    value TEXT
  )
`);

async function startServer() {
  const app = express();
  const PORT = 3000;
  app.use(express.json());

  app.get("/api/state", (req, res) => {
    try {
      const rows = db.prepare("SELECT key, value FROM store").all() as { key: string, value: string }[];
      const state: Record<string, any> = {};
      for (const row of rows) {
        state[row.key] = JSON.parse(row.value);
      }
      res.json(state);
    } catch (err) {
      console.error(err);
      res.json({});
    }
  });

  app.post("/api/state/:key", (req, res) => {
    const { key } = req.params;
    const value = JSON.stringify(req.body);
    
    try {
      db.prepare(`
        INSERT INTO store (key, value) VALUES (@key, @value)
        ON CONFLICT(key) DO UPDATE SET value = @value
      `).run({ key, value });
      res.json({ success: true });
    } catch (err) {
      console.error(err);
      res.status(500).json({ error: "Failed to update state variable" });
    }
  });

  if (process.env.NODE_ENV !== "production") {
    const vite = await createViteServer({
      server: { middlewareMode: true },
      appType: "spa",
    });
    app.use(vite.middlewares);
  } else {
    const distPath = path.join(process.cwd(), 'dist');
    app.use(express.static(distPath));
    app.get('*', (req, res) => {
      res.sendFile(path.join(distPath, 'index.html'));
    });
  }

  app.listen(PORT, "0.0.0.0", () => {
    console.log(`Server running on http://localhost:${PORT}`);
  });
}

startServer();
